    cap = '<p class="small" style="margin:6px 0 11px">Jedes Logo liegt als SVG (Vektor, für Web und Druck) und als PNG mit transparentem Grund (für Canva, Office, E-Mail) vor. Die Dateien „tokens.css“ und „Markentrix_Bild-CI_ChatGPT.md“ sind auf Version 3.1 zu aktualisieren (Salz, Reif, Kupferknopf).</p>'
    pl = card('<h2>Prüfliste vor jeder Veröffentlichung</h2>' + lst(['Logo aus dem CI-Paket, unverändert, mit Schutzraum', 'Grund in Salz, Weiß oder Reif, dunkle Fläche nur als Akzent', 'Nur Archivo und Source Sans 3', 'Text in Tiefsee, Hauptknopf in Kupfer mit Tiefsee-Text', 'Kupfer: ein Hauptknopf und höchstens ein Wort je Überschrift', 'Kein Verlauf, kein Violett, kein Cyan', 'Genau eine Hauptaktion', 'Jede Zahl und jede Referenz ist belegt und freigegeben', 'Schreibweisen nach Seite 5, Anrede Sie', 'Bild besteht die sieben Prüfungen von Seite 21'], 'c'))
    um = card('<h2>Umstellung des Bestands</h2>' + ol(['<b>Website markentrix.de:</b> umgestellt am 17.11.2026, gilt mit dem nächsten Upload', '<b>Social-Vorschaubilder:</b> alle 87 neu erzeugt (Salz, Kupferwort)', '<b>Profilbilder</b> auf Instagram, Facebook, YouTube, TikTok, Google und WhatsApp', '<b>E-Mail-Signatur und Mailvorlagen:</b> Knopf in Kupfer', '<b>Canva-Markenkit:</b> Farben, Schriften, Logos, Vorlagen',
                                                     '<b>Kundenportal:</b> Logo und Farben der Markentrix-Oberfläche', '<b>Vorlagen:</b> Angebot, Rechnung, Präsentation', '<b>Druck:</b> Visitenkarten nach Andruck'], 'n') + '<p class="small" style="margin-top:6px">In dieser Reihenfolge wird am schnellsten sichtbar, dass sich etwas geändert hat.</p>')
    zu = card('<h2>Zuständigkeit</h2>' + kv([('Freigabe der CI', 'Christian Wien, Inhaber'), ('Änderungen', 'Nur als neue Version dieses Handbuchs'), ('Dienstleister', 'Erhalten das CI-Paket vollständig'), ('KI-Werkzeuge', 'Erhalten dieses Handbuch und die Bild-CI')], 'w'))
    ve = card('<h2>Versionen</h2><table class="kv w"><tr><td style="color:%s;width:34px">1.0</td><td style="font-weight:400">2026 · White / Light Premium, Erstfassung mit Verlauf</td></tr><tr><td style="color:%s;width:34px">2.0</td><td style="font-weight:400">November 2026 · vollständiges Regelwerk, noch im alten Erscheinungsbild</td></tr>'
              '<tr><td style="color:%s;width:34px">3.0</td><td style="font-weight:400">November 2026 · neues Erscheinungsbild: Pfauenblau, Kupfer, Leinen, Kreide, Archivo, Source Sans 3</td></tr><tr><td style="color:%s;width:34px">3.1</td><td style="font-weight:400">November 2026 · Salz und Reif statt Kreide und Leinen, Kupfer als Handlungsfarbe, Kupferwort statt Kupferstrich, Farbflächen im Wechsel</td></tr></table>' % (PFAU, PFAU, PFAU, PFAU))
    return page(26, 'Praxis', 'Dateien & Umstellung', 'Dateien &amp; ' + k('Umstellung'), 'Eine CI wirkt nur, wenn alle dieselben Dateien verwenden. Das CI-Paket ist die einzige Quelle. Ältere Logo-Dateien werden gelöscht.',
                ft + cap + '<div class="g g2" style="align-items:stretch">' + pl + um + '</div><div class="g g2 mt2" style="align-items:stretch">' + zu + ve + '</div>')


